css:
.cat-progress{width:220px;height:4px;border-radius:var(--cat-size-radius-pill);background:rgba(0,0,0,.10);overflow:hidden}
.cat-progress>.fill{height:100%;border-radius:inherit;background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));transition:width var(--cat-motion-slow) var(--cat-motion-ease-out)}
.cat-progress.indeterminate>.fill{width:38%!important;animation:cat-indet 1.2s var(--cat-motion-ease-out) infinite}
@keyframes cat-indet{0%{transform:translateX(-110%)}100%{transform:translateX(300%)}}
.cat-spinner{width:18px;height:18px;border-radius:50%;border:2px solid var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));border-top-color:transparent;animation:cat-spin .7s linear infinite;display:inline-block}
.cat-skeleton{border-radius:var(--cat-size-radius-sm);background:linear-gradient(90deg,rgba(0,0,0,.05) 25%,rgba(0,0,0,.10) 37%,rgba(0,0,0,.05) 63%);background-size:400% 100%;animation:cat-shimmer 1.4s ease infinite}
@keyframes cat-shimmer{0%{background-position:100% 0}100%{background-position:-100% 0}}
.cat-skeleton.text{height:10px;margin:6px 0}
.cat-skeleton.av{width:36px;height:36px;border-radius:50%}
